//! `cargo xtask divergence-book [--out PATH] [--check] [--strict]`: renders the DIVERGENCES book from the register
//! of `docs/COMPATIBILITY.md` §5 and the per-ID rationale files `docs/divergences/<ID>.md` (ADR-071), for WP-37's
//! user documentation (`xtask docs` includes the generated file).
//!
//! The book has one chapter per register class (§5.1 CRASH … §5.9 TIERB) and one section per ID: the register
//! summary, the reproduction status of its scenario (`tests/differential/divergences/<ID>.yaml`: `active`, `unit`,
//! `stub`), and the rationale file's body (its own `# <ID>` title dropped, its headings demoted under the ID). The
//! default output is `target/docs/DIVERGENCES.md`. `--check` renders nothing and fails when a register ID lacks
//! either file or a file names no register ID; with `--strict` it also fails while any rationale or scenario is
//! still a W0 stub.
//!
//! Owner: WP-35.

use std::ffi::OsString;
use std::fmt::Write as _;
use std::path::{Path, PathBuf};

use anyhow::{Context as _, bail};

use crate::workspace::{self, say};

/// One register row.
#[derive(Debug, Clone)]
struct Entry {
    id: String,
    section: String,
    summary: String,
    owners: Vec<String>,
}

/// The rows of the §5 tables (`| D-… | … | WP |`), with the `### 5.x` heading they sit under.
fn parse_register(md: &str) -> Vec<Entry> {
    let mut out = Vec::new();
    let mut section = String::new();
    let mut inside = false;
    for line in md.lines() {
        if let Some(h) = line.strip_prefix("## ") {
            inside = h.starts_with("5.");
            continue;
        }
        if let Some(h) = line.strip_prefix("### ") {
            inside = h.starts_with("5.");
            if inside {
                h.clone_into(&mut section);
            }
            continue;
        }
        if !inside || !line.starts_with("| D-") {
            continue;
        }
        let cells: Vec<&str> = line
            .trim()
            .trim_matches('|')
            .split(" | ")
            .map(str::trim)
            .collect();
        let (Some(id), Some(wp)) = (cells.first(), cells.last()) else {
            continue;
        };
        let summary = cells
            .len()
            .checked_sub(2)
            .and_then(|i| cells.get(i))
            .copied()
            .unwrap_or_default();
        out.push(Entry {
            id: (*id).to_owned(),
            section: section.clone(),
            summary: summary.to_owned(),
            owners: wp
                .split(',')
                .map(str::trim)
                .filter(|w| !w.is_empty() && w.bytes().all(|b| b.is_ascii_digit()))
                .map(|w| format!("WP-{w}"))
                .collect(),
        });
    }
    out
}

/// `status:` of a scenario file (`active` when absent), or `missing`.
fn scenario_status(path: &Path) -> String {
    let Ok(text) = std::fs::read_to_string(path) else {
        return String::from("missing");
    };
    text.lines()
        .find_map(|l| l.strip_prefix("status:"))
        .map_or_else(
            || String::from("active"),
            |s| s.trim().trim_matches('"').to_owned(),
        )
}

fn doc_is_stub(text: &str) -> bool {
    text.contains("To be written by") || text.contains("**Status:** stub")
}

/// The rationale body: the `# <ID>` title line dropped, headings demoted by two levels.
fn body(text: &str, id: &str) -> String {
    let mut out = String::new();
    let mut in_fence = false;
    for line in text.lines() {
        if line.starts_with("```") {
            in_fence.toggle();
        }
        if !in_fence && line.trim() == format!("# {id}") {
            continue;
        }
        if !in_fence && line.starts_with('#') {
            out.push_str("##");
        }
        out.push_str(line);
        out.push('\n');
    }
    out.trim().to_owned()
}

/// The GitHub-style anchor of a heading made of an ID.
fn anchor(id: &str) -> String {
    id.to_ascii_lowercase()
}

fn render(root: &Path, entries: &[Entry]) -> anyhow::Result<String> {
    let mut o = String::new();
    o.push_str("# Divergences from pre-commit 4.7.0\n\n");
    o.push_str(
        "<!-- Generated by `cargo xtask divergence-book` from docs/COMPATIBILITY.md §5 and docs/divergences/*.md; \
         do not edit. -->\n\n",
    );
    o.push_str(
        "snp reproduces pre-commit 4.7.0 byte for byte (COMPATIBILITY §2). Every deliberate difference is listed \
         here, with the reason it is safe and a reproduction. Each one is pinned by a differential scenario that must \
         keep diverging (`tests/differential/divergences/<ID>.yaml`) or, where the CLI cannot reach it, by unit \
         tests.\n\n",
    );
    o.push_str("| ID | snp | Scenario |\n|---|---|---|\n");
    for e in entries {
        let st =
            scenario_status(&root.join(format!("tests/differential/divergences/{}.yaml", e.id)));
        writeln!(
            o,
            "| [{}](#{}) | {} | {st} |",
            e.id,
            anchor(&e.id),
            e.summary
        )
        .unwrap_or_default();
    }
    let mut section = "";
    for e in entries {
        if e.section != section {
            section = &e.section;
            writeln!(o, "\n## {section}").unwrap_or_default();
        }
        let doc = root.join(format!("docs/divergences/{}.md", e.id));
        let text =
            std::fs::read_to_string(&doc).with_context(|| format!("reading {}", doc.display()))?;
        writeln!(o, "\n### {}\n", e.id).unwrap_or_default();
        writeln!(o, "{}\n", body(&text, &e.id)).unwrap_or_default();
    }
    Ok(o)
}

/// Problems that always fail (`missing`, `orphan`) and stubs (fail with `--strict`).
fn check(root: &Path, entries: &[Entry]) -> anyhow::Result<(Vec<String>, Vec<String>)> {
    let mut problems = Vec::new();
    let mut stubs = Vec::new();
    for e in entries {
        let doc = root.join(format!("docs/divergences/{}.md", e.id));
        match std::fs::read_to_string(&doc) {
            Ok(t) if doc_is_stub(&t) => {
                stubs.push(format!("{} rationale ({})", e.id, e.owners.join(", ")));
            }
            Ok(_) => {}
            Err(_) => problems.push(format!("{}: missing {}", e.id, workspace::rel(root, &doc))),
        }
        let yaml = root.join(format!("tests/differential/divergences/{}.yaml", e.id));
        match scenario_status(&yaml).as_str() {
            "missing" => {
                problems.push(format!("{}: missing {}", e.id, workspace::rel(root, &yaml)));
            }
            "stub" => stubs.push(format!("{} scenario ({})", e.id, e.owners.join(", "))),
            _ => {}
        }
    }
    for (dir, ext) in [
        ("docs/divergences", "md"),
        ("tests/differential/divergences", "yaml"),
    ] {
        let d = root.join(dir);
        for f in std::fs::read_dir(&d)
            .with_context(|| format!("reading {}", d.display()))?
            .flatten()
        {
            let p = f.path();
            let stem = p
                .file_stem()
                .map_or_default(|s| s.to_string_lossy().into_owned());
            if p.extension().is_some_and(|x| x == ext)
                && stem != "README"
                && !entries.iter().any(|e| e.id == stem)
            {
                problems.push(format!(
                    "{}: not in COMPATIBILITY §5",
                    workspace::rel(root, &p)
                ));
            }
        }
    }
    Ok((problems, stubs))
}

/// Runs the task with the arguments that follow its name.
pub(crate) fn run(args: &[OsString]) -> anyhow::Result<()> {
    let root = workspace::root()?;
    let mut out: PathBuf = root.join("target/docs/DIVERGENCES.md");
    let mut only_check = false;
    let mut strict = false;
    let mut it = args.iter();
    while let Some(a) = it.next() {
        match a.to_string_lossy().as_ref() {
            "--out" => out = PathBuf::from(it.next().context("--out needs a path")?),
            "--check" => only_check = true,
            "--strict" => strict = true,
            other => bail!(
                "usage: cargo xtask divergence-book [--out PATH] [--check] [--strict] (got {other:?})"
            ),
        }
    }
    let md = std::fs::read_to_string(root.join("docs/COMPATIBILITY.md"))
        .context("reading docs/COMPATIBILITY.md")?;
    let entries = parse_register(&md);
    if entries.is_empty() {
        bail!("docs/COMPATIBILITY.md: no register rows in §5");
    }
    let (problems, stubs) = check(&root, &entries)?;
    for p in &problems {
        say(&format!("PROBLEM: {p}"));
    }
    if !stubs.is_empty() {
        say(&format!(
            "{} unfilled stub(s): {}",
            stubs.len(),
            stubs.join("; ")
        ));
    }
    if !problems.is_empty() {
        bail!("{} divergence-register problem(s)", problems.len());
    }
    if strict && !stubs.is_empty() {
        bail!("--strict: {} stub(s) remain", stubs.len());
    }
    if only_check {
        say(&format!(
            "divergence register: {} IDs, files consistent",
            entries.len()
        ));
        return Ok(());
    }
    let book = render(&root, &entries)?;
    if let Some(parent) = out.parent() {
        std::fs::create_dir_all(parent)
            .with_context(|| format!("creating {}", parent.display()))?;
    }
    std::fs::write(&out, book).with_context(|| format!("writing {}", out.display()))?;
    say(&format!(
        "wrote {} ({} divergences)",
        out.display(),
        entries.len()
    ));
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn register_and_body() {
        let md = "## 5. Register\n### 5.1 CRASH — x\n| ID | a | b | WP |\n| D-CRASH-01 | pc | snp | 21, 13 |\n## 6. Other\n| D-X-01 | q | 1 |\n";
        let e = parse_register(md);
        assert_eq!(e.len(), 1);
        assert_eq!(
            e[0].owners,
            vec![String::from("WP-21"), String::from("WP-13")]
        );
        assert_eq!(e[0].section, "5.1 CRASH — x");
        let b = body(
            "# D-CRASH-01\n\ntext\n\n## Rationale\n\n```sh\n# not a heading\n```\n",
            "D-CRASH-01",
        );
        assert_eq!(b, "text\n\n#### Rationale\n\n```sh\n# not a heading\n```");
        assert!(doc_is_stub("To be written by WP-32"));
    }

    #[test]
    fn the_workspace_book_renders() {
        let root = workspace::root().unwrap();
        let md = std::fs::read_to_string(root.join("docs/COMPATIBILITY.md")).unwrap();
        let entries = parse_register(&md);
        assert!(entries.len() >= 80);
        let (problems, _stubs) = check(&root, &entries).unwrap();
        assert!(problems.is_empty(), "{problems:?}");
        let book = render(&root, &entries).unwrap();
        assert!(book.contains("\n### D-DIAG-05\n"));
        assert!(book.contains("## 5.1 CRASH"));
        assert_eq!(
            scenario_status(&root.join("tests/differential/divergences/D-SEC-07.yaml")),
            "unit"
        );
    }
}
